<?php
require_once __DIR__.'/common.php';require_admin(); require_staff();
$edit=null;if(isset($_GET['edit'])){$s=$conn->prepare('SELECT * FROM chuyenmuc WHERE machuyenmuc=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}
$cats=$conn->query('SELECT madanhmuc,tendanhmuc FROM danhmuc WHERE trang_thai=1 ORDER BY tendanhmuc')->fetchAll();
$rows=$conn->query('SELECT c.*,d.tendanhmuc FROM chuyenmuc c LEFT JOIN danhmuc d ON d.madanhmuc=c.madanhmuc ORDER BY c.machuyenmuc DESC')->fetchAll();
admin_header('QUẢN LÝ CHUYÊN MỤC');
?><section class="panel"><h2><?=$edit?'Sửa chuyên mục':'Thêm chuyên mục'?></h2><form method="post" action="xulyquanlychuyenmuc.php"><input type="hidden" name="_csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="<?=$edit?'update':'create'?>"><input type="hidden" name="machuyenmuc" value="<?=h($edit['machuyenmuc']??'')?>"><div class="grid"><div class="field"><label>Tên chuyên mục *</label><input name="tenchuyenmuc" required maxlength="150" value="<?=h($edit['tenchuyenmuc']??'')?>"></div><div class="field"><label>Danh mục cha</label><select name="madanhmuc"><option value="">-- Chọn danh mục --</option><?php foreach($cats as $c):?><option value="<?=$c['madanhmuc']?>" <?=((int)($edit['madanhmuc']??0)===(int)$c['madanhmuc']?'selected':'')?>><?=h($c['tendanhmuc'])?></option><?php endforeach;?></select></div><div class="field"><label>Thể loại</label><input name="theloai" value="<?=h($edit['theloai']??'')?>"></div><div class="field"><label>Trạng thái</label><select name="trang_thai"><option value="1" <?=((int)($edit['trang_thai']??1)===1?'selected':'')?>>Hiển thị</option><option value="0" <?=((int)($edit['trang_thai']??1)===0?'selected':'')?>>Ẩn</option></select></div></div><div class="field"><label>Mô tả ngắn</label><textarea name="motangan"><?=h($edit['motangan']??'')?></textarea></div><button><?=$edit?'Lưu thay đổi':'Thêm chuyên mục'?></button><?php if($edit):?> <a class="btn secondary" href="quanlychuyenmuc.php">Hủy</a><?php endif;?></form></section>
<div class="table-wrap"><table><thead><tr><th>ID</th><th>Chuyên mục</th><th>Danh mục cha</th><th>Thể loại</th><th>Mô tả</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=$r['machuyenmuc']?></td><td><?=h($r['tenchuyenmuc'])?></td><td><?=h($r['tendanhmuc']??'Chưa phân loại')?></td><td><?=h($r['theloai'])?></td><td><?=h($r['motangan'])?></td><td><?=$r['trang_thai']?'Hiển thị':'Ẩn'?></td><td><div class="actions"><a class="btn small" href="?edit=<?=$r['machuyenmuc']?>">Sửa</a><form method="post" action="xulyquanlychuyenmuc.php" onsubmit="return confirm('Xóa chuyên mục? Tin tức sẽ không bị xóa.');"><input type="hidden" name="_csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="machuyenmuc" value="<?=$r['machuyenmuc']?>"><button class="danger small">Xóa</button></form></div></td></tr><?php endforeach;?></tbody></table></div><?php admin_footer();?>
